// Helper function to get random words.
// Usa shuffleArray (Fisher-Yates, definido abaixo) em vez de sort(() => Math.random() - 0.5):
// esse padrão de "shuffle por sort" não sorteia com distribuição uniforme.
export const getRandomWords = (count, excludeIds = []) => {
  const available = words.filter((_, i) => !excludeIds.includes(i));
  return shuffleArray(available).slice(0, count);
};

// Helper to shuffle array
export const shuffleArray = (arr) => {
  const shuffled = [...arr];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
};
